/bin/zsh -lc './mvnw -q -pl sm-shop dependency:build-classpath -Dmdep.outputFile=/tmp/shopizer-sm-shop-classpath && SHOPIZER_CP="sm-shop-model/target/classes:$(cat /tmp/shopizer-sm-shop-classpath)" jshell --class-path "$SHOPIZER_CP" <<'"'EOF'
import javax.validation.Validation;
import com.salesmanager.shop.model.catalog.manufacturer.PersistableManufacturer;
var validator = Validation.buildDefaultValidatorFactory().getValidator();
var valid = new PersistableManufacturer();
valid.setWebsite(\"https://example.com\");
var invalid = new PersistableManufacturer();
invalid.setWebsite(\"example.com\");
System.out.println(validator.validate(valid).size());
System.out.println(validator.validate(invalid).iterator().next().getPropertyPath());
EOF"

